#include <iostream>
int main() {
    unsigned int a = 5; // binary: 0000 0101
    int b = -8; // binary (two's complement): 1111 1000
    auto leftShift = a << 2; // shifts bits of 'a' left by 2 positions
    auto rightShiftUnsigned = a >> 1; // shifts bits of 'a' right by 1 position
    auto rightShiftSigned = b >> 2; // implementation-defined for signed negative
    std::cout << "a << 2 = " << leftShift << '\n';
    std::cout << "a >> 1 = " << rightShiftUnsigned << '\n';
    std::cout << "b >> 2 = " << rightShiftSigned << '\n';
    return 0;
}
